@MainActor func transient_BoardModel_boardLimitsBezierPaths (
       _ self_modelWidth : CanariLength,                     
       _ self_modelHeight : CanariLength
) -> BezierPathArray {
//--- START OF USER ZONE 2
  let modelWidth = self_modelWidth
  let modelHeight = self_modelHeight
  let left    = CanariLength.zero
  let right   = modelWidth
  let bottom  = CanariLength.zero
  let top     = modelHeight
  var bp = BezierPath ()
  bp.move (to : CanariPoint (x: left,  y: bottom))
  bp.line (to : CanariPoint (x: left,  y: top))
  bp.line (to : CanariPoint (x: right, y: top))
  bp.line (to : CanariPoint (x: right, y: bottom))
  bp.close ()
  bp.lineWidth = BOARD_LIMIT_WIDTH
  bp.lineCapStyle = .round
  var array = BezierPathArray ()
  array.append (bp)
  return array
//--- END OF USER ZONE 2
}

